import{_ as t,o as a,c as n,a5 as i}from"./chunks/framework.bIR-4glx.js";const g=JSON.parse('{"title":"English Diagnostic: Four-skill Baseline and Transfer Record","description":"Preserve listening, reading, speaking, and writing first versions, conditions, errors, feedback, delayed retests, and CEFR direction without replacing ability evidence with averages or polished work.","frontmatter":{"title":"English Diagnostic: Four-skill Baseline and Transfer Record","description":"Preserve listening, reading, speaking, and writing first versions, conditions, errors, feedback, delayed retests, and CEFR direction without replacing ability evidence with averages or polished work.","updated":"2026-10-19T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/english-diagnostic.en.md","name":"english-diagnostic.en.md"}},"headers":[],"relativePath":"en/templates/english-diagnostic.md","filePath":"en/templates/english-diagnostic.md","lastUpdated":1792368000000}'),s={name:"en/templates/english-diagnostic.md"};function r(d,e,l,o,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="english-diagnostic-four-skill-baseline-and-transfer-record" tabindex="-1">English Diagnostic: Four-skill Baseline and Transfer Record <a class="header-anchor" href="#english-diagnostic-four-skill-baseline-and-transfer-record" aria-label="Permalink to &quot;English Diagnostic: Four-skill Baseline and Transfer Record&quot;">​</a></h1><p>This is the full four-skill diagnostic worksheet, not the five-minute starting task or an exam that pins a person to A1-C2. To begin with one small action, use the <a href="./../topics/english-diagnostic">English Diagnostic hub</a> for a five-minute baseline in one skill. For a full diagnostic, choose one real topic and complete listening, reading, speaking, and writing first versions under comparable time and explicit limits, then retest a parallel task after seven days and one real delivery after thirty days.</p><p>Copy this card into a private note. Do not include passwords, customer records, identity documents, medical privacy, unauthorised third-party material, or exam content that may not be recorded.</p><h2 id="_1-define-the-diagnostic-boundary" tabindex="-1">1. Define the Diagnostic Boundary <a class="header-anchor" href="#_1-define-the-diagnostic-boundary" aria-label="Permalink to &quot;1. Define the Diagnostic Boundary&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># English Diagnostic - YYYY-MM-DD</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Real context: work / study / job search / life / other</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Real topic:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Audience or conversation partner:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest shared delivery across four skills:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Start/end dates:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Material, version, and source:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Shared limits (time, device, environment):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Permitted dictionary / captions / translation / search / AI / human help:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Privacy, copyright, exam, and expert-responsibility boundary:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Day-7 parallel-task date:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Day-30 retest date:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Week-12 real-task date:</span></span></code></pre></div><p>The four tasks need not use identical material. Keep topic, difficulty, time, and acceptance standards comparable enough to interpret. For a real role, do not let one overall level replace the language actions in the job description.</p><h2 id="_2-four-first-version-tasks" tabindex="-1">2. Four First-version Tasks <a class="header-anchor" href="#_2-four-first-version-tasks" aria-label="Permalink to &quot;2. Four First-version Tasks&quot;">​</a></h2><p>Complete the first version without looking things up or asking AI to answer or rewrite. Finish first, then mark where support was needed.</p><table tabindex="0"><thead><tr><th>Skill</th><th>Suggested first version</th><th>Minimum delivery</th></tr></thead><tbody><tr><td>Listening</td><td>Hear a real 2-4 minute clip once</td><td>Main point, three certain details, responsibility/next step, and 60-second retelling</td></tr><tr><td>Reading</td><td>Read a real 600-1000-word text</td><td>Five-line main thread, one evidence location, and one challenge or unknown</td></tr><tr><td>Speaking</td><td>Record an unscripted two-minute explanation, experience, or process</td><td>Listener can retell purpose, key facts, and next step</td></tr><tr><td>Writing</td><td>Write a 180-250-word email, explanation, or argument in 20 minutes</td><td>Reader knows conclusion, support, limits, and action</td></tr></tbody></table><p>Do not flatten genuine differences to make the four skills look equal. The diagnostic should show where ability works, not manufacture a flattering average.</p><h2 id="_2a-record-collaboration-dimensions-when-needed" tabindex="-1">2A. Record Collaboration Dimensions When Needed <a class="header-anchor" href="#_2a-record-collaboration-dimensions-when-needed" aria-label="Permalink to &quot;2A. Record Collaboration Dimensions When Needed&quot;">​</a></h2><p>Add the tasks below when your goal includes remote collaboration, customer communication, classroom discussion, or family learning. They are not new levels and do not need to be tested every time; keep evidence when they affect a real outcome.</p><table tabindex="0"><thead><tr><th>Task dimension</th><th>10–15 minute sample</th><th>Evidence location and result</th></tr></thead><tbody><tr><td>Mediation and retelling</td><td>Read two short texts with different positions and explain each claim, difference, and unknown</td><td>Listener distinguishes the source, your retelling, and your inference;</td></tr><tr><td>Online interaction</td><td>Write one progress update, one blocker, and the next step so the other person can continue without a meeting</td><td>The other person knows the owner, timing, and missing information;</td></tr><tr><td>Repairing misunderstanding</td><td>Ask for clarification, then restate shared understanding and open questions</td><td>The other person confirms accuracy and the next action did not change because of a guess;</td></tr></tbody></table><p>Do not use a speaking or writing score as a substitute when one of these is a high-risk part of the role. Keep the sample, audience feedback, and next parallel task together.</p><h2 id="_3-preserve-the-first-version-and-conditions" tabindex="-1">3. Preserve the First Version and Conditions <a class="header-anchor" href="#_3-preserve-the-first-version-and-conditions" aria-label="Permalink to &quot;3. Preserve the First Version and Conditions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>First-version location</th><th>Start/end</th><th>Tools and cues</th><th>Completed?</th><th>Main uncertainty</th></tr></thead><tbody><tr><td>Listening</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Reading</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Speaking</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Writing</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I can still explain independently:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Condition I would most like to change:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Conclusion this first version cannot support:</span></span></code></pre></div><h2 id="_4-score-impact-not-feeling" tabindex="-1">4. Score Impact, Not Feeling <a class="header-anchor" href="#_4-score-impact-not-feeling" aria-label="Permalink to &quot;4. Score Impact, Not Feeling&quot;">​</a></h2><p>Score each <code>0-2</code>: <code>0=no evidence/not completed</code>, <code>1=partial, cue-dependent, or unstable</code>, <code>2=independent under current conditions</code>. Give every number an evidence location.</p><table tabindex="0"><thead><tr><th>Skill</th><th style="text-align:right;">Task completion</th><th style="text-align:right;">Comprehensibility</th><th style="text-align:right;">Accuracy/range</th><th style="text-align:right;">Organisation/fluency</th><th style="text-align:right;">Independence/transfer</th><th>Evidence reason</th></tr></thead><tbody><tr><td>Listening</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Reading</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Speaking</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Writing</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><h3 id="scoring-meaning" tabindex="-1">Scoring Meaning <a class="header-anchor" href="#scoring-meaning" aria-label="Permalink to &quot;Scoring Meaning&quot;">​</a></h3><ul><li><strong>Task completion</strong>: did information and intention arrive, and can the action continue?</li><li><strong>Comprehensibility</strong>: could a real reader/listener understand without excessive guessing?</li><li><strong>Accuracy and range</strong>: did vocabulary, grammar, pronunciation, spelling, and detail support the task?</li><li><strong>Organisation/fluency</strong>: did structure, order, pauses, or layout obstruct use?</li><li><strong>Independence/transfer</strong>: can the task return after recent cues are removed and one condition changes?</li></ul><p>Use totals only for your own longitudinal comparison, never as a personality, intelligence, or hiring label. For CEFR direction, combine this with <a href="./../threads/part-1/0-cefr">CEFR Goals and Self-check</a> rather than turning one diagnostic into a permanent level.</p><h2 id="_5-choose-one-primary-barrier-per-skill" tabindex="-1">5. Choose One Primary Barrier per Skill <a class="header-anchor" href="#_5-choose-one-primary-barrier-per-skill" aria-label="Permalink to &quot;5. Choose One Primary Barrier per Skill&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Primary barrier</th><th>Sample/timestamp</th><th>Task impact</th><th>Smallest next repair</th><th>Evidence card</th></tr></thead><tbody><tr><td>Listening</td><td>vocabulary / sound / syntax / background / attention / device</td><td></td><td></td><td></td><td><a href="./listening-audit">Listening Evidence Card</a></td></tr><tr><td>Reading</td><td>vocabulary / structure / background / evidence / layout / capacity</td><td></td><td></td><td></td><td><a href="./reading-evidence">Reading Evidence Card</a></td></tr><tr><td>Speaking</td><td>chunks / pronunciation / organisation / interaction / register / follow-up</td><td></td><td></td><td></td><td><a href="./speaking-evidence">Speaking Evidence Card</a></td></tr><tr><td>Writing</td><td>task / fact / structure / sentence / register / delivery</td><td></td><td></td><td></td><td><a href="./writing-evidence">Writing Evidence Card</a></td></tr></tbody></table><p>If a barrier cannot be tied to a sample or timestamp, do not treat it as a conclusion yet. A learner may know many words and still fail to segment speech, or be accurate while unable to organise an asynchronous handover.</p><h2 id="_6-design-one-targeted-repair" tabindex="-1">6. Design One Targeted Repair <a class="header-anchor" href="#_6-design-one-targeted-repair" aria-label="Permalink to &quot;6. Design One Targeted Repair&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One barrier I will repair:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Repair action (25-45 minutes):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Material and source:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Minimum scaffold allowed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Acceptance standard:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Before/after samples to preserve:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Feedback that would change the plan:</span></span></code></pre></div><p>Usually protect meaning and task completion first, then facts and structure, then high-impact vocabulary, grammar, pronunciation, or register. Leave style details that do not change the result until later.</p><h2 id="_7-delayed-retest-and-transfer" tabindex="-1">7. Delayed Retest and Transfer <a class="header-anchor" href="#_7-delayed-retest-and-transfer" aria-label="Permalink to &quot;7. Delayed Retest and Transfer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Remove</th><th>Change</th><th>Output</th><th>Result/evidence</th></tr></thead><tbody><tr><td>Day 1</td><td>Answers after first version</td><td>Original conditions</td><td>Repair version</td><td></td></tr><tr><td>Day 7</td><td>Recent cues and old sentences</td><td>Parallel topic or audience</td><td>Same kind of task</td><td></td></tr><tr><td>Day 30</td><td>Tool conversation and comments</td><td>Real source or time pressure</td><td>One real delivery</td><td></td></tr><tr><td>Week 12</td><td>Old task and score</td><td>Target role, course, or life context</td><td>Complete task</td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I can still do independently on day 7:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Error that still returns on day 30:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Skill that succeeded only on a familiar topic:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Where extra time would most affect life:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What this retest cannot prove:</span></span></code></pre></div><h2 id="_8-record-ai-translation-and-human-feedback" tabindex="-1">8. Record AI, Translation, and Human Feedback <a class="header-anchor" href="#_8-record-ai-translation-and-human-feedback" aria-label="Permalink to &quot;8. Record AI, Translation, and Human Feedback&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Tool / model / version and date:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Samples that existed before tool use:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What it did: diagnosis / questions / counterexample / transcript / feedback / other</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope generated or rewritten:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Primary source, dictionary, teacher, peer, or real-audience check:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Suggestions accepted, rejected, or deferred and why:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Independent sample after closing the tool:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Disclosure required by school, client, employer, or exam:</span></span></code></pre></div><p>Model answers, speech-recognition scores, and polished final prose cannot independently prove ability. Important judgments return to original material, actual response, and a named accountable owner.</p><h2 id="_9-decide-the-next-cycle" tabindex="-1">9. Decide the Next Cycle <a class="header-anchor" href="#_9-decide-the-next-cycle" aria-label="Permalink to &quot;9. Decide the Next Cycle&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Current component direction (not a permanent level):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Strongest real evidence:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Weakest evidence with the largest life impact:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Continue:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Downgrade:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Change variable:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pause or seek help:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest next task:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next review date:</span></span></code></pre></div><p>Related entry points: <a href="./../threads/part-1/1-understanding">Learning Principles: Turn Effort into Verifiable Learning</a> | <a href="./vocabulary-audit">Vocabulary Evidence Card</a> | <a href="./grammar-evidence">Grammar Evidence Card</a> | <a href="./listening-audit">Listening Evidence Card</a> | <a href="./reading-evidence">Reading Evidence Card</a> | <a href="./speaking-evidence">Speaking Evidence Card</a> | <a href="./writing-evidence">Writing Evidence Card</a> | <a href="./evidence-chain">Evidence Chain</a></p>`,38)])])}const k=t(s,[["render",r]]);export{g as __pageData,k as default};
